def transform(grid):
    # The marker is a seed for a four-connected zero region; color that region only.
    from collections import deque
    h,w=len(grid),len(grid[0])
    marks=[(r,c,v) for r,row in enumerate(grid) for c,v in enumerate(row) if v not in (0,3)]
    if not marks:
        return [row[:] for row in grid]
    color=marks[0][2]
    out=[row[:] for row in grid]
    q=deque(); seen=set()
    for r,c,_ in marks:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc] in (0,color) and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    while q:
        r,c=q.popleft(); out[r][c]=color
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc] in (0,color) and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return out

