def transform(grid):
    h,w=len(grid),len(grid[0])
    # The unique non-background/nonzero color marks a motif. Copy its occupied
    # offsets onto each location where all motif offsets currently contain 0.
    colors={v for row in grid for v in row if v not in (0,3)}
    if not colors:
        return [row[:] for row in grid]
    color=next(iter(colors))
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
    r0=min(r for r,c in pts); c0=min(c for r,c in pts)
    shape={(r-r0,c-c0) for r,c in pts}
    rh=max(dr for dr,dc in shape)+1; cw=max(dc for dr,dc in shape)+1
    out=[row[:] for row in grid]
    for r in range(h-rh+1):
        for c in range(w-cw+1):
            if all(grid[r+dr][c+dc]==0 for dr,dc in shape):
                for dr,dc in shape:
                    out[r+dr][c+dc]=color
    return out
